  color:var(--ect-7fe82d94);
}
#stv1 .delta-sel {
  background:var(--ect-18762874);
  color:var(--ect-23737986);
}
#stv1 .step-tooltip {
  display:none;
  position:absolute;
  pointer-events:none;
  z-index:100;
  background:var(--ect-a461f39e);
  border:1px solid var(--ect-8bf7af61);
  border-radius:6px;
  padding:6px 10px;
  font-size:11.5px;
  line-height:1.5;
  color:var(--ect-8a2de1d4);
  box-shadow:0 2px 8px rgba(0,0,0,var(--ect-5b1a4381));
  max-width:220px;
  white-space:nowrap;
}
#stv1 .step-tooltip.visible {
  display:block;
}
#stv1 .step-tooltip .tt-label {
  font-weight:600;
  font-size:12px;
}
#stv1 .step-tooltip .tt-state {
  font-size:10.5px;
  margin-top:2px;
  opacity:0.75;
}
#stv1 .step-notches {
  position:absolute;
  left:0; top:0; bottom:0;
  width:20px;
  display:flex;
  flex-direction:column;
  justify-content:center;
  gap:1px;
  padding:8px 0;
  z-index:50;
  cursor:pointer;
}
#stv1 .step-notch {
  width:4px;
  height:4px;
  min-height:2px;
  border-radius:1px;
  margin-left:4px;
  opacity:0.35;
  transition:opacity 0.15s ease, background 0.15s ease;
}
#stv1 .step-notch.active {
  opacity:1;
  width:5px;
}
#stv1 .step-overlay {
  display:none;
  position:absolute;
  left:0; top:0;
  width:80%;
  max-height:80%;
  overflow-y:auto;
  background:var(--ect-6014f0e9);
  backdrop-filter:blur(12px);
  -webkit-backdrop-filter:blur(12px);
  border-radius:0 8px 8px 0;
  border:1px solid var(--ect-834734eb);
  border-left:none;
  box-shadow:0 4px 24px rgba(0,0,0,var(--ect-78ff349c));
  z-index:60;
  padding:6px 0;
  font-size:11.5px;
}
#stv1 .step-overlay.visible {
  display:block;
}
#stv1 .sl-item {
  display:flex;
  align-items:center;
  gap:6px;
  padding:5px 10px;
  cursor:pointer;
  transition:background 0.1s ease;
}
#stv1 .sl-item:hover {
  background:var(--ect-063ead49);
}
#stv1 .sl-item.active {
  background:color-mix(in srgb, var(--ect-07ab1f6a) 13%, transparent);
  border-left:2px solid var(--ect-07ab1f6a);
}
#stv1 .sl-num {
  color:var(--ect-0e6f4dd6);
  font-size:10px;
  min-width:18px;
  text-align:right;
  flex-shrink:0;
}
#stv1 .sl-badge {
  font-size:9px;
  font-weight:600;
  padding:1px 5px;
  border-radius:3px;
  flex-shrink:0;
  white-space:nowrap;
}
#stv1 .sl-method {
  color:var(--ect-8a2de1d4);
  font-size:11px;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
#stv1 .sl-group-header {
  display:flex;
  align-items:center;
  gap:6px;
  padding:6px 10px 2px 10px;
  font-size:11px;
  opacity:0.8;
  border-top:1px solid var(--ect-c5b2b11f);
  margin-top:2px;
}
#stv1 .sl-group-count {
  color:var(--ect-0e6f4dd6);
  font-size:9px;
  margin-left:auto;
  flex-shrink:0;
}
#stv1 .sl-item.sl-sub {
  padding-left:28px;
}
#stv1 .sl-sub-label {
  color:var(--ect-8a2de1d4);
  font-size:10.5px;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
#stv1 .tl-bracket {
  position:absolute;
  bottom:0;
  height:2px;
  border-radius:1px;
  opacity:0.6;
  pointer-events:none;
}
