      // Scaled from zero, so the smallest value (such as the least flow) still shows
      emvMin=Math.min(0,Math.min.apply(null,evals));
      emvMax=Math.max.apply(null,evals);
      if(emvMax===emvMin) emvMax=emvMin+1;
